+struct ConcurrentWriter {
+  std::unordered_map<string, vector<shared_ptr<Buffer>>> todo;
+  std::unordered_map<string, int> locks;
+  std::atomic<int64_t> todoBytes = 0;
+  std::atomic<int64_t> writtenBytes = 0;
+
+  vector<std::thread> threads;
