+      {
+        std::lock_guard<std::mutex> lockT(mtx_todo);
+        std::lock_guard<std::mutex> lockJ(mtx_join);
+
+        bool nothingTodo = todo.size() == 0;
+
+        if (nothingTodo && joinRequested) {
+          return;
+        } else {
+          auto it = todo.begin();
+          while (it != todo.end()) {
+            if (locks.find(it->first) == locks.end()) break;
+            it++;
+          }
+          if (it != todo.end()) {
+            path = it->first;
+            work = it->second;
+            todo.erase(it);
+            locks[path] = 1;
+          }
+        }
